/* ── часы пролога: якорь → строка и секунда ── */
const ПрологЧасы={
 слова(t){return String(t||"").match(/[а-яёА-ЯЁa-zA-Z0-9]+/g)||[];},
 норм(w){return String(w||"").toLowerCase().replace(/ё/g,"е");},
 /* «k:слово#n+0.3» | «k:^» (начало строки) | «k:$» (конец) | «0:+1.2» (от начала сцены) */
 якорь(i,a){
  const m=String(a).match(/^(\d+):([^+\-#]*)(?:#(\d+))?([+\-]\d+(?:\.\d+)?)?$/);if(!m)return null;
  const k=Number(m[1]),сл=this.норм(m[2]||"").trim(),n=Math.max(1,Number(m[3])||1),сдвиг=Number(m[4])||0;
  if(k===0)return {k:0,t:Math.max(0,сдвиг)};
  const s=PROLOGUE[i];if(!s||!s.строки[k-1])return null;
  const ключ=`s${i+1}_${k}`,wt=PROLOG_WT[ключ];
  const x=s.строки[k-1],текст=typeof x==="string"?x:x.t;
  const ws=this.слова(текст).map(w=>this.норм(w));
  const d=wt?wt.d:Math.max(1.5,текст.length/13);
  let t;
  if(!сл||сл==="^")t=0;
  else if(сл==="$")t=d;
  else{let idx=-1,c=0;for(let j=0;j<ws.length;j++)if(ws[j]===сл&&++c===n){idx=j;break;}
   if(idx<0)return null;
   t=wt&&wt.w&&wt.w[idx]!=null?wt.w[idx]:d*idx/Math.max(1,ws.length);}
  return {k,t:Math.max(0,t+сдвиг),d};}};

/* ── (15.5) ШИРЬ, ГЛУБИНА И ВЫСОТА ПРОЛОГА ──
   Просьба игрока: «расширь стереопанораму пролога, добавь глубину звука и высоту звука». Было: звуки частей
   стояли тесной дугой впереди — из 208 точечных звуков 82 ровно по центру, сбоку два, сзади 35; высоты не было
   ни у одного; рой боя и похода — только спереди; петли фона — как записаны, а записаны многие узко (у гор
   связь каналов 0,81, у города 0,69) или в один канал (птицы, листва, костёр осады, колёса, гул руин).
   Стало:
   • угол — каждый звук части разведён по углу в 1,6 раза (до ±170°: сбоку и за спиной), звуки ровно по
     центру разошлись на 18–40° — каждый в свою, всегда одну и ту же сторону; не трогается то, что случается
     с самим слушателем (шёпот у уха, сердце, переход, ион, портал). Рой боя и похода — во всю ширь спереди,
     а доля «кругом» — сбоку и за спиной: войско идёт вокруг слушателя, сеча — со всех сторон;
   • глубина — дальнее отодвинуто дальше (расстояние за первой клеткой — в полтора раза), у дальнего воздух
     съедает верх (с полутора клеток: 20 кГц → 4,5 кГц на двенадцати), и чем дальше звук, тем больше в нём
     отзвука места: близкое сухое, дальнее тонет в эхе. У каждой части своя акустика — ночная улица, гулкая
     пустота первого звука, зал руин, горы перевала, вода у брода, город, лес пробуждения;
   • высота — гром, птицы, драконы, колокола на башнях, стрелы, камни и осыпь со склонов звучат сверху,
     подземный гул, землетрясение и провал портала — снизу, шаги — под ногами; бойцы на склонах над тропой —
     выше уха. Восьмое число звука части задаёт высоту явно;
   • петли фона и слоёв — через ширитель середины и сторон (M/S): сторона усилена тем больше, чем уже запись,
     к одноканальной добавлена развязанная сторона (середина через задержку 13 мс без баса) — сумма каналов
     прежняя, громкость уравнена. У «небесных» петель (морось, дождь, снег, пепел, листва, птицы, ветер на
     высоте) — приподнята полоса около 8 кГц: по ней ухо слышит звук сверху. Стерео-звуки «плоско» (проезд
     машины, гром, клич войска) — через тот же ширитель. Без объёмного звука (настройка, файл://) всё звучит
     по-прежнему. */
